def solve():
    total_sum = sum(range(1, 192))

    # Case d=2: R = {2, 4, ..., 190}
    R_d2 = [i for i in range(2, 192, 2)]
    if len(R_d2) >= 95:
        sum_R_d2 = sum(R_d2)
        remaining_sum_d2 = total_sum - sum_R_d2
        print(f"d=2, sum_R={sum_R_d2}, remaining={remaining_sum_d2}")
    else:
        print("d=2 too small")

    # Case d=1: R = {k, k+1, ..., 191}
    # We need 192-k >= 95 => k <= 97
    for k in range(1, 98):
        R_consecutive = list(range(k, 192))
        # Check rule (i): If x is removed, 2x is also removed
        valid_i = True
        for x in R_consecutive:
            if 2*x <= 191 and 2*x not in R_consecutive:
                valid_i = False
                break
        if not valid_i:
            continue

        # Check rule (ii): If x and y are removed, x+y is also removed
        valid_ii = True
        # Checking rule (ii) is more expensive, so let's use a set for faster lookups
        R_set = set(R_consecutive)
        for i in range(len(R_consecutive)):
            for j in range(i, len(R_consecutive)):
                x, y = R_consecutive[i], R_consecutive[j]
                if x + y <= 191 and (x + y) not in R_set:
                    valid_ii = False
                    break
            if not valid_ii:
                break

        if valid_ii:
            sum_R = sum(R_consecutive)
            remaining = total_sum - sum_R
            print(f"d=1, consecutive k={k}, sum_R={sum_R}, remaining={remaining}")

solve()
